using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketInput
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public class CombinedTextOutput
{
    public string CombinedText { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedLabel { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

public class TicketRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

public class TicketPredictionResponse
{
    public string Category { get; set; } = string.Empty;
    public float Confidence { get; set; }
}

using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public interface ITicketModelService
{
    MulticlassClassificationMetrics TrainAndEvaluate();
    PredictionEngine<TicketInput, TicketPrediction> GetPredictionEngine();
}

public class TicketModelService : ITicketModelService
{
    private readonly MLContext _mlContext;
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<TicketModelService> _logger;
    private ITransformer? _model;

    public TicketModelService(ILogger<TicketModelService> logger)
    {
        _mlContext = new MLContext(seed: 42);
        _dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        _modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
        _logger = logger;
    }

    public MulticlassClassificationMetrics TrainAndEvaluate()
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.3);

        var pipeline = _mlContext.Transforms.CustomMapping<TicketInput, CombinedTextOutput>(
                (input, output) => output.CombinedText = $"{input.Subject} {input.Description}",
                contractName: "CombineText")
            .Append(_mlContext.Transforms.Text.FeaturizeText("TextFeatures", "CombinedText"))
            .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label", "Category"))
            .Append(_mlContext.Transforms.Concatenate("Features", "TextFeatures", "Priority"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(split.TrainSet);

        var predictions = _model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        _logger.LogInformation(
            "Model metrics — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);

        Directory.CreateDirectory(Path.GetDirectoryName(_modelPath)!);
        _mlContext.Model.Save(_model, split.TrainSet.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        return metrics;
    }

    public PredictionEngine<TicketInput, TicketPrediction> GetPredictionEngine()
    {
        if (_model is null)
            throw new InvalidOperationException("Model has not been trained. Call TrainAndEvaluate first.");

        return _mlContext.Model.CreatePredictionEngine<TicketInput, TicketPrediction>(_model);
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketsController : ControllerBase
{
    private readonly ITicketModelService _modelService;
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;

    public TicketsController(
        ITicketModelService modelService,
        PredictionEnginePool<TicketInput, TicketPrediction> predictionPool)
    {
        _modelService = modelService;
        _predictionPool = predictionPool;
    }

    [HttpPost("train")]
    public IActionResult Train()
    {
        var metrics = _modelService.TrainAndEvaluate();

        return Ok(new
        {
            metrics.MicroAccuracy,
            metrics.MacroAccuracy,
            metrics.LogLoss
        });
    }

    [HttpPost("predict")]
    public IActionResult Predict([FromBody] TicketRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        var confidence = prediction.Score?.Length > 0
            ? prediction.Score.Max()
            : 0f;

        return Ok(new TicketPredictionResponse
        {
            Category = prediction.PredictedLabel,
            Confidence = confidence
        });
    }
}

